{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required input fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list):
        raise ValueError("nodes must be a list")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    required = set(required_symbols)
    by_id = {}
    original_order = []
    required_node_fields = ("id", "parent", "symbol", "depth", "removable", "utility")

    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in required_node_fields:
            if field not in node:
                raise ValueError("node missing required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str):
            raise ValueError("node id must be a string")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be a boolean")
        if not isinstance(utility, (int, float)) or isinstance(utility, bool):
            raise ValueError("utility must be numeric")

        by_id[node_id] = node
        original_order.append(node_id)

    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is not None and parent not in by_id:
            raise ValueError("parent id does not reference a node")
        if parent == node_id:
            raise ValueError("node cannot be its own parent")

    children = {node_id: [] for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is not None:
            children[parent].append(node_id)

    retained = set(by_id)
    removed = []

    def required_symbols_still_represented(candidate_id):
        represented = set()
        for kept_id in retained:
            if kept_id != candidate_id:
                represented.add(by_id[kept_id]["symbol"])
        return required.issubset(represented)

    candidates = sorted(
        by_id.values(),
        key=lambda node: (-node["depth"], node["id"]),
    )

    for node in candidates:
        node_id = node["id"]
        if node_id not in retained:
            continue
        if node["parent"] is None:
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        if not required_symbols_still_represented(node_id):
            continue

        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
